import{z as o,x as i,o as l,c as d,q as s,j as r,D as t,d as a,s as B,S as n,b as e}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"自指令与指令演化","description":"","frontmatter":{"title":"自指令与指令演化","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/self-instruct-evol.md","filePath":"llm/self-instruct-evol.md","lastUpdated":1791063341000}'),p={name:"llm/self-instruct-evol.md"};function D(C,E,u,c,f,m){const A=i("Mermaid");return l(),d("div",null,[E[2]||(E[2]=s('<h1 id="自指令与指令演化" tabindex="-1">自指令与指令演化 <a class="header-anchor" href="#自指令与指令演化" aria-label="Permalink to &quot;自指令与指令演化&quot;">​</a></h1><div class="epigraph"><p>自举把种子变成题池，演化把题池推向更难；两者都没有凭空造出分布，只是沿着种子所在的邻域把覆盖摊开。</p><footer>—— 据 Wang 等 Self-Instruct 2022；Xu 等 Evol-Instruct 整理</footer></div><p><a href="/llm/synthetic-taxonomy">上一课</a>把生产线切成来源、真值、用途三轴，其中「有源改写」是成本最低、最常用的一条：不要求教师会做新题，只要求它围绕种子受控地变异。本课写这条线的两个原型——Self-Instruct 的自举与 Evol-Instruct 的演化。<a href="/llm/self-instruct">自指令课</a>与 <a href="/llm/evol-instruct">Evol-Instruct</a>已讲过它们的机制与谱系地位，本课的增量是工程视角：管线参数怎么定、每一步在控制什么、变异打开覆盖的同时把什么风险放了进来。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>自举的原型管线是：一百多条种子指令 → 生成新指令 → 为每条指令生成实例 → 过滤 → 入库。工程问题藏在四步之间的参数里：新指令从哪个池子采样（种子池还是已生成池）决定多样性收敛还是发散；近重复用什么阈值；指令与实例分开生成还是一起生成。演化的原型管线是：对种子施加变异算子——加深（加约束、多步化）或换面（换领域、换问法）——再用过滤器决定去留。共同的问题是：变异的方向不受你控制，教师偏爱变异到自己会做的区域，题池会整体漂向「可出可解」的浅水区。</p><p><span class="marginnote">「自举」（bootstrap）来自「拽着自己的靴带把自己提起来」：用模型生成的题再喂回给模型，滚雪球式扩大题池。好处是几乎不要人工标注；风险是近亲繁殖——池子滚得越大，越像教师自己口味的回音。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>自举管线四个旋钮。指令与实例分步生成：先抽指令再补实例，任务分布由指令层控制；一起生成会让实例风格反绑指令分布，题池塌向教师高频任务族。近重复控制用 ROUGE-L 或嵌入相似度阈值，\\(0.7\\) 是 Self-Instruct 的原口径——阈值低了近重复涌入，高了多样性还没长出来就被掐掉，阈值要用池内多样性曲线校，不是常数。启发式过滤拦格式坏样本：答案缺失、拒答开头、过长过短。最后是生成环内去重：每生成一批先与池内比对再决定入库；事后清洗挡不住已经污染多样性统计的批次。</p><p><span class="marginnote">阈值 \\(0.7\\) 怎么理解：ROUGE-L 取值 0 到 1，越接近 1 两句话越像。0.7 意味着「最长公共子序列重合约七成就算近重复、拦下」。它是一道闸门：调松了近亲涌入，调紧了多样性还没长出来就被掐掉。</span></p><p>演化管线三个部件。算子表：加深与换面要成对配置，只加深会让题池整体右移到没人会做，只换面会停在浅层。回退规则：变异产物生成失败、答案缺失或自相矛盾时回退到原样本；回退率本身是监控指标，回退率飙升说明算子步子迈过了教师能力。fitness 过滤：Evol-Instruct 用一个判别器分辨「演化指令」与「平庸指令」——这一步就是上一课谱系里的裁判打分档，裁判偏置照例要单独管。</p>',10)),(l(),r(n,null,{default:t(()=>[B(A,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20SEED%5B%22%E7%A7%8D%E5%AD%90%E6%B1%A0%22%5D%20--%3E%20GEN%5B%22%E7%94%9F%E6%88%90%E6%96%B0%E6%8C%87%E4%BB%A4%22%5D%0A%20%20GEN%20--%3E%20INST%5B%22%E5%88%86%E6%AD%A5%E7%94%9F%E6%88%90%E5%AE%9E%E4%BE%8B%22%5D%0A%20%20INST%20--%3E%20DEDUP%7B%22%E8%BF%91%E9%87%8D%E5%A4%8D%E9%98%88%E5%80%BC%22%7D%0A%20%20DEDUP%20--%3E%7C%E9%87%8D%E5%A4%8D%7C%20DROP%5B%22%E4%B8%A2%E5%BC%83%22%5D%0A%20%20DEDUP%20--%3E%7C%E9%80%9A%E8%BF%87%7C%20HEUR%5B%22%E5%90%AF%E5%8F%91%E5%BC%8F%E8%BF%87%E6%BB%A4%22%5D%0A%20%20HEUR%20--%3E%20POOL%5B%22%E6%8C%87%E4%BB%A4%E6%B1%A0%22%5D%0A%20%20POOL%20--%3E%20EVOL%5B%22%E6%BC%94%E5%8C%96%E7%AE%97%E5%AD%90%EF%BC%9A%E5%8A%A0%E6%B7%B1%E4%B8%8E%E6%8D%A2%E9%9D%A2%22%5D%0A%20%20EVOL%20--%3E%20FIT%7B%22fitness%20%E4%B8%8E%E5%9B%9E%E9%80%80%E8%A7%84%E5%88%99%22%7D%0A%20%20FIT%20--%3E%7C%E5%A4%B1%E8%B4%A5%7C%20BACK%5B%22%E5%9B%9E%E9%80%80%E5%8E%9F%E6%A0%B7%E6%9C%AC%EF%BC%8C%E5%9B%9E%E9%80%80%E7%8E%87%E5%85%A5%E7%9B%91%E6%8E%A7%22%5D%0A%20%20FIT%20--%3E%7C%E9%80%9A%E8%BF%87%7C%20POOL%0A"})]),fallback:t(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e("h2",{id:"机制",tabindex:"-1"},[a("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=e("p",null,[a("为什么分步生成能控制分布：指令层的采样分布是显式参数，实例只是条件补全；一起生成时任务分布隐在教师的自发倾向里，人无法再对它配比。为什么演化能打开覆盖：对种子施加小变异等价于在种子邻域做受控探索，比自由采样命中率高，但探索半径由算子强度决定——半径小则覆盖不开，半径大则回退率与噪声齐升。自举与演化共享一个更深的机制：池子越滚越大，新生成样本的边际多样性在掉，因为池内高频模式会被采样进来再被加强。这是数据飞轮的早期形态，"),e("a",{href:"/llm/data-flywheel-stop"},"数据飞轮的停止条件"),a("的仪表——held-out 边际增量与生成分布熵——在自举管线上从第一轮就该挂上，而不是等闭环成型。")],-1)),(l(),r(n,null,{default:t(()=>[B(A,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20VAR%5B%22%E6%BC%94%E5%8C%96%E7%AE%97%E5%AD%90%E5%BC%BA%E5%BA%A6%EF%BC%88%E5%8F%98%E5%BC%82%E5%8D%8A%E5%BE%84%EF%BC%89%22%5D%20--%3E%7C%22%E5%A4%AA%E5%B0%8F%22%7C%20SMALL%5B%22%E8%A6%86%E7%9B%96%E6%89%93%E4%B8%8D%E5%BC%80%EF%BC%8C%E9%A2%98%E6%B1%A0%E6%8C%A4%E5%9C%A8%E7%A7%8D%E5%AD%90%E9%82%BB%E5%9F%9F%22%5D%0A%20%20VAR%20--%3E%7C%22%E9%80%82%E4%B8%AD%22%7C%20GOOD%5B%22%E8%A6%86%E7%9B%96%E6%91%8A%E5%BC%80%EF%BC%8C%E5%9B%9E%E9%80%80%E7%8E%87%E5%8F%AF%E6%8E%A7%22%5D%0A%20%20VAR%20--%3E%7C%22%E5%A4%AA%E5%A4%A7%22%7C%20BIG%5B%22%E5%9B%9E%E9%80%80%E7%8E%87%E9%A3%99%E5%8D%87%EF%BC%8C%E5%99%AA%E5%A3%B0%E9%BD%90%E6%B6%A8%22%5D%0A%20%20MON%5B%22%E7%9B%91%E6%8E%A7%EF%BC%9A%E5%9B%9E%E9%80%80%E7%8E%87%20%2B%20held-out%20%E8%BE%B9%E9%99%85%E5%A2%9E%E9%87%8F%22%5D%20--%3E%20TUNE%5B%22%E6%8D%AE%E6%AD%A4%E5%9B%9E%E8%B0%83%E7%AE%97%E5%AD%90%E5%BC%BA%E5%BA%A6%22%5D%0A"})]),fallback:t(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=s('<p><span class="marginnote">Self-Instruct 用约 175 条种子滚出 5.2 万指令；Alpaca 换强教师重跑同一条管线。种子量级与产出并不同比例放大——瓶颈在「生成加过滤」的循环质量，不在种子的绝对数量。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>自举与演化只解决指令侧的扩张，不解决回答侧的质量：指令对了，答案可以是错的，实例级验证留给本课程后面的质量过滤课。多样性上限被种子池锁死——种子不含的任务族，演化算子变不出来，覆盖审计要相对真实任务分布做，不能只在池内比较。此外，演化的「更难」与「更好」不等价：加深算子制造的约束可能只是啰嗦，难度要留给后面的难度分级课用通过率重标，不能听教师自评的。</p><p><span class="marginnote">可以类比一个题库编辑团队：自举负责「照着样题再出五万道」，演化负责「把简单题往难里改」。但出题再勤快也不保证标准答案是对的——出题与判卷必须分开验收，这正是「指令侧扩张不等于回答侧质量」的日常版本。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>自举四旋钮：指令实例分步、近重复阈值、启发式过滤、环内去重。</li><li>演化三部件：算子表成对配、回退规则、fitness 裁判。</li><li>回退率与 held-out 边际增量从第一轮就是监控项。</li><li>指令侧扩张不等于回答侧质量；种子池锁死多样性上限。</li><li>「更难」要用通过率重标，不听教师自评。</li><li>出处：Wang 等 Self-Instruct 2022；Xu 等 WizardLM 2023；Taori 等 Alpaca 2023。</li></ul>',6))])}const _=o(p,[["render",D]]);export{F as __pageData,_ as default};
